// ── Haversine distance in km ──────────────────────────────
function haversineKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
    Math.cos((lat2 * Math.PI) / 180) *
    Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// ── Get nearby stations sorted by distance ────────────────
export function getNearbyStations(lat, lng, limitKm = 50, maxCount = 10) {
  return STATIONS
    .map(s => ({ ...s, distanceKm: haversineKm(lat, lng, s.lat, s.lng) }))
    .filter(s => s.distanceKm <= limitKm)
    .sort((a, b) => a.distanceKm - b.distanceKm)
    .slice(0, maxCount);
}

// ── Get stations by state ─────────────────────────────────
export function getStationsByState(stateName) {
  return STATIONS.filter(s =>
    s.state.toLowerCase() === stateName.toLowerCase()
  );
}

// ── Get stations by district ──────────────────────────────
export function getStationsByDistrict(district, stateName) {
  return STATIONS.filter(
    s => s.district === district && s.state.toLowerCase() === stateName.toLowerCase()
  );
}

// ── Detect state from GPS ─────────────────────────────────
export function detectStateFromGPS(lat, lng) {
  const nearest = STATIONS
    .map(s => ({ state: s.state, dist: haversineKm(lat, lng, s.lat, s.lng) }))
    .sort((a, b) => a.dist - b.dist)[0];
  return nearest?.state || null;
}

// ── Get all unique states ─────────────────────────────────
export function getAllStates() {
  return [...new Set(STATIONS.map(s => s.state))].sort();
}

// ── Verify station login ──────────────────────────────────
export function verifyStation(code, password) {
  return STATIONS.find(
    s => s.code === code.toUpperCase() && s.password === password
  ) || null;
}

export default STATIONS;